import { effect, onCleanup, signal } from '@vorzelajs/core'
import { createContext, For, Portal, useContext } from '@vorzelajs/dom'
import { cx } from '~/lib/cx.ts'
import type { ReactNode } from '~/lib/types.ts'
import { Bell, CircleAlert, CircleCheck, Info, TriangleAlert, X } from './icons.tsx'
import type { LucideIcon } from './icons.tsx'
import styles from './sonner.module.scss'

export type ToastType = 'default' | 'success' | 'error' | 'warning' | 'info'

export interface Toast {
  id: string
  title?: string
  description?: string
  type?: ToastType
  duration?: number
  action?: { label: string; onClick: () => void }
}

export interface ToasterContextValue {
  toast: (toast: Omit<Toast, 'id'>) => string
  dismiss: (id: string) => void
}

const ToasterContext = createContext<ToasterContextValue | null>(null, 'toaster')

/** The most recently mounted toaster, used by the imperative `toast`. */
let activeToaster: ToasterContextValue | null = null

export function useToast(): ToasterContextValue {
  const context = useContext(ToasterContext)
  if (!context) throw new Error('useToast must be used within <Toaster>')
  return context
}

export type ToasterPosition =
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'
  | 'top-center'
  | 'bottom-center'

const POSITION: Record<ToasterPosition, string> = {
  'top-left': styles.topLeft,
  'top-right': styles.topRight,
  'top-center': styles.topCenter,
  'bottom-left': styles.bottomLeft,
  'bottom-right': styles.bottomRight,
  'bottom-center': styles.bottomCenter,
}

const TYPE: Record<ToastType, string> = {
  default: styles.default,
  success: styles.success,
  error: styles.error,
  warning: styles.warning,
  info: styles.info,
}

const TYPE_ICON: Record<ToastType, LucideIcon> = {
  default: Bell,
  success: CircleCheck,
  error: CircleAlert,
  warning: TriangleAlert,
  info: Info,
}

export function Toaster({
  position = 'bottom-right',
  children,
}: {
  position?: ToasterPosition
  children?: ReactNode
}) {
  const [toasts, setToasts] = signal<Toast[]>([])
  const timers = new Map<string, ReturnType<typeof setTimeout>>()

  const dismiss = (id: string): void => {
    const timer = timers.get(id)
    if (timer) {
      clearTimeout(timer)
      timers.delete(id)
    }
    setToasts((previous) => previous.filter((item) => item.id !== id))
  }

  const toast = (input: Omit<Toast, 'id'>): string => {
    const id = Math.random().toString(36).slice(2, 9)
    const duration = input.duration ?? 4000
    const item: Toast = { ...input, id, duration }
    setToasts((previous) => [...previous, item])

    if (duration > 0) {
      const timer = setTimeout(() => dismiss(id), duration)
      timer.unref?.()
      timers.set(id, timer)
    }
    return id
  }

  const value: ToasterContextValue = { toast, dismiss }

  effect(() => {
    activeToaster = value
    onCleanup(() => {
      if (activeToaster === value) activeToaster = null
    })
  })

  onCleanup(() => {
    for (const timer of timers.values()) clearTimeout(timer)
    timers.clear()
  })

  return (
    <ToasterContext.Provider value={value}>
      {children}
      <Portal>
        <div className={cx(styles.viewport, POSITION[position])}>
          <For each={toasts} key={(item) => item.id}>
            {(item, index) => {
              const type = item.type ?? 'default'
              const Icon = TYPE_ICON[type]
              return (
                <div
                  className={cx(styles.toast, TYPE[type])}
                  role={type === 'error' ? 'alert' : 'status'}
                  aria-live={type === 'error' ? 'assertive' : 'polite'}
                  aria-atomic="true"
                  style={{ animationDelay: `${index * 40}ms` }}
                >
                  <span className={styles.typeIcon}>
                    <Icon aria-hidden />
                  </span>
                  <div className={styles.copy}>
                    {item.title ? <p className={styles.title}>{item.title}</p> : null}
                    {item.description ? (
                      <p className={styles.description}>{item.description}</p>
                    ) : null}
                  </div>
                  {item.action ? (
                    <button
                      type="button"
                      className={styles.action}
                      onClick={() => {
                        item.action?.onClick()
                        dismiss(item.id)
                      }}
                    >
                      {item.action.label}
                    </button>
                  ) : null}
                  <button
                    type="button"
                    className={styles.dismiss}
                    onClick={() => dismiss(item.id)}
                    aria-label="Dismiss notification"
                  >
                    <X aria-hidden />
                  </button>
                </div>
              )
            }}
          </For>
        </div>
      </Portal>
    </ToasterContext.Provider>
  )
}

/**
 * Imperative fallback for callers outside a component tree. Prefer
 * `useToast()` so the toast is rendered by the nearest <Toaster>.
 */
export function toast(input: Omit<Toast, 'id'>): string {
  if (activeToaster) return activeToaster.toast(input)
  console.warn('Use useToast() hook from Toaster context')
  return ''
}

export { Toaster as Sonner }

@use 'styles' as vz;

.viewport {
  position: fixed;
  z-index: vz.z('toast');
  display: flex;
  width: 23rem;
  max-width: calc(100vw - #{vz.space(6)});
  flex-direction: column;
  gap: vz.space(2.5);
  padding: 0;
  pointer-events: none;
}

.top-left {
  top: calc(#{vz.space(4)} + env(safe-area-inset-top, 0px));
  left: vz.space(4);
}

.top-right {
  top: calc(#{vz.space(4)} + env(safe-area-inset-top, 0px));
  right: vz.space(4);
}

.top-center {
  top: calc(#{vz.space(4)} + env(safe-area-inset-top, 0px));
  left: 50%;
  translate: -50% 0;
}

.bottom-left {
  bottom: calc(#{vz.space(4)} + env(safe-area-inset-bottom, 0px));
  left: vz.space(4);
}

.bottom-right {
  right: vz.space(4);
  bottom: calc(#{vz.space(4)} + env(safe-area-inset-bottom, 0px));
}

.bottom-center {
  bottom: calc(#{vz.space(4)} + env(safe-area-inset-bottom, 0px));
  left: 50%;
  translate: -50% 0;
}

.toast {
  --toast-accent: #{vz.color('muted-foreground')};
  --toast-tint: #{vz.color('muted')};

  display: flex;
  align-items: flex-start;
  gap: vz.space(2.5);
  width: 100%;
  padding: vz.space(3);
  border: 1px solid vz.color('border', 0.72);
  border-radius: vz.radius('lg');
  background: vz.color('popover', 0.86);
  color: vz.color('popover-foreground');
  box-shadow:
    vz.elevation(3),
    0 1px 0 hsl(0deg 0% 100% / 60%) inset;
  backdrop-filter: blur(20px) saturate(180%);
  pointer-events: auto;
  animation: vz-toast-in 260ms vz.ease('spring') both;

  @include vz.motion-reduce {
    animation: none;
  }
}

:global(.dark) .toast {
  box-shadow:
    0 16px 40px hsl(0deg 0% 0% / 45%),
    0 1px 0 hsl(210deg 40% 98% / 8%) inset;
}

.default {
  --toast-accent: #{vz.color('foreground')};
  --toast-tint: #{vz.color('muted')};
}

.success {
  --toast-accent: #{vz.color('success')};
  --toast-tint: #{vz.color('success', 0.12)};
}

.error {
  --toast-accent: #{vz.color('destructive')};
  --toast-tint: #{vz.color('destructive', 0.1)};
}

.warning {
  --toast-accent: #{vz.color('warning')};
  --toast-tint: #{vz.color('warning', 0.14)};
}

.info {
  --toast-accent: #{vz.color('info')};
  --toast-tint: #{vz.color('info', 0.12)};
}

.type-icon {
  display: inline-flex;
  width: 1.5rem;
  height: 1.5rem;
  flex: none;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
  border-radius: vz.radius('full');
  background: var(--toast-tint);
  color: var(--toast-accent);

  svg {
    @include vz.icon(3.5);
  }
}

.copy {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 2px;
}

.title {
  margin: 0;
  font-size: vz.font-size('sm');
  font-weight: 600;
  line-height: 1.35;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.45;
}

.dismiss {
  display: inline-flex;
  width: 1.5rem;
  height: 1.5rem;
  flex: none;
  align-items: center;
  justify-content: center;
  margin: -2px -2px 0 0;
  border: 0;
  border-radius: vz.radius('xs');
  background: transparent;
  color: vz.color('muted-foreground');
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('foreground', 0.06);
    color: vz.color('foreground');
  }

  @include vz.focus-ring(2px, 1px, 0.6);

  svg {
    @include vz.icon(3);
  }

  @include vz.motion-reduce {
    transition: none;
  }
}

.action {
  display: inline-flex;
  flex: none;
  align-items: center;
  align-self: center;
  height: 1.75rem;
  padding-inline: vz.space(2.5);
  border: 1px solid vz.color('border');
  border-radius: vz.radius('sm');
  background: vz.color('accent');
  color: vz.color('accent-foreground');
  font-size: 0.6875rem;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color vz.duration('fast') vz.ease('out'),
    border-color vz.duration('fast') vz.ease('out');

  @include vz.hover {
    background: vz.color('muted');
    border-color: vz.color('foreground', 0.2);
  }

  @include vz.focus-ring(2px, 1px, 0.6);
}

@include vz.up('sm') {
  .viewport {
    width: 24rem;
  }
}

@include vz.down('sm') {
  .viewport {
    right: vz.space(3);
    left: vz.space(3);
    width: auto;
    max-width: none;
  }

  .top-center,
  .bottom-center {
    translate: 0 0;
  }
}

@keyframes vz-toast-in {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.97);
  }

  to {
    opacity: 1;
    transform: none;
  }
}
